// Drives the payment form without postbacks. Server-authored values arrive through
// the hidden fields that Default.aspx.cs fills on load.
(function () {
  "use strict";

  function serverValue(id) {
    return document.getElementById(id).value;
  }

  var paymentsEnabled = serverValue("PaymentsEnabledHidden") === "True";
  var gatewayBaseUrl  = serverValue("GatewayBaseUrlHidden");

  function postPayment(accountNumber, amount) {
    return fetch("api/payments", {
      method:  "POST",
      headers: { "Content-Type": "application/json" },
      body:    JSON.stringify({ accountNumber: accountNumber, amount: amount })
    }).then(function (response) { return response.json(); });
  }

  function getPayment(paymentId) {
    return fetch("api/payments/" + encodeURIComponent(paymentId))
      .then(function (response) { return response.json(); });
  }

  document.addEventListener("DOMContentLoaded", function () {
    var form = document.getElementById("paymentForm");
    if (!paymentsEnabled) {
      form.hidden = true;
      return;
    }
    form.addEventListener("submit", function (event) {
      event.preventDefault();
      postPayment(form.elements.accountNumber.value, Number(form.elements.amount.value))
        .then(function (result) {
          document.getElementById("paymentStatus").textContent =
            result.status + " (balance " + result.accountBalance + ")";
        });
    });
  });

  window.estatePortal = { postPayment: postPayment, getPayment: getPayment, gatewayBaseUrl: gatewayBaseUrl };
})();
using System;
using System.Web.UI;

namespace Estate.Portal.Pages
{
    /// <summary>
    /// Renders server-authored values into hidden fields once, on load. Nothing posts back;
    /// portal.js reads the fields and talks to the portal's own Web API from then on.
    /// </summary>
    public partial class Default : Page
    {
        protected void Page_Load(object sender, EventArgs e)
        {
            PaymentsEnabledHidden.Value = Globals.PaymentsEnabled.ToString();
            GatewayBaseUrlHidden.Value  = Globals.GatewayBaseUrl;
        }
    }
}
using System.Threading.Tasks;
using System.Web.Http;

using Estate.Portal.Models;
using Estate.Portal.Services;

namespace Estate.Portal.Controllers
{
    /// <summary>Receives the browser's payment requests and forwards them to the gateway.</summary>
    public class PaymentsController : ApiController
    {
        private readonly GatewayClient gateway = new GatewayClient(Globals.GatewayBaseUrl);

        [HttpPost]
        [Route("api/payments")]
        public async Task<IHttpActionResult> Post(PaymentRequestModel request)
        {
            if (!Globals.PaymentsEnabled)
            {
                return BadRequest("Payments are disabled.");
            }
            PaymentResultModel result = await gateway.PostPaymentAsync(request);
            return Ok(result);
        }

        [HttpGet]
        [Route("api/payments/{paymentId}")]
        public async Task<IHttpActionResult> Get(string paymentId)
        {
            PaymentResultModel result = await gateway.GetPaymentAsync(paymentId);
            return Ok(result);
        }
    }
}
using System;
using System.Net.Http;
using System.Threading.Tasks;

using Estate.Portal.Models;

namespace Estate.Portal.Services
{
    /// <summary>
    /// HTTP client for the payments gateway. The gateway is a separate deployment in the
    /// same cloud; the only ties are the base URL in Web.config and the route strings here.
    /// </summary>
    public sealed class GatewayClient
    {
        private static readonly HttpClient Http = new HttpClient();

        private readonly Uri baseUrl;

        public GatewayClient(string baseUrl)
        {
            this.baseUrl = new Uri(baseUrl);
        }

        public async Task<PaymentResultModel> PostPaymentAsync(PaymentRequestModel request)
        {
            HttpResponseMessage response = await Http.PostAsJsonAsync(new Uri(baseUrl, "api/payments"), request);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<PaymentResultModel>();
        }

        public async Task<PaymentResultModel> GetPaymentAsync(string paymentId)
        {
            HttpResponseMessage response = await Http.GetAsync(new Uri(baseUrl, "api/payments/" + paymentId));
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<PaymentResultModel>();
        }
    }
}
using System.Web.Http;

using Estate.Contracts;
using Estate.Gateway.Wcf;

namespace Estate.Gateway.Controllers
{
    /// <summary>Bridges the portal's REST calls into WCF calls on the on-prem hub.</summary>
    public class PaymentsController : ApiController
    {
        private readonly HubProxy hub = new HubProxy();

        [HttpPost]
        [Route("api/payments")]
        public IHttpActionResult Post(PaymentRequest request)
        {
            request.Workload    = GatewaySettings.Workload;
            request.Environment = GatewaySettings.Environment;
            return Ok(hub.PostPayment(request));
        }

        [HttpGet]
        [Route("api/payments/{paymentId}")]
        public IHttpActionResult Get(string paymentId)
        {
            var query = new PaymentQuery
            {
                PaymentId   = paymentId,
                Workload    = GatewaySettings.Workload,
                Environment = GatewaySettings.Environment
            };
            return Ok(hub.GetPayment(query));
        }
    }
}
using System;
using System.ServiceModel;

using Estate.Contracts;

namespace Estate.Gateway.Wcf
{
    /// <summary>
    /// Client side of the hub contract. The endpoint address lives in Web.config under the
    /// "PaymentHub" client endpoint; the hub itself is another deployment, on-prem.
    /// </summary>
    public sealed class HubProxy
    {
        public const string EndpointName = "PaymentHub";

        public PaymentResult PostPayment(PaymentRequest request) => Call(hub => hub.PostPayment(request));

        public PaymentResult GetPayment(PaymentQuery query) => Call(hub => hub.GetPayment(query));

        private static T Call<T>(Func<IPaymentHub, T> operation)
        {
            var factory = new ChannelFactory<IPaymentHub>(EndpointName);
            IPaymentHub channel = factory.CreateChannel();
            try
            {
                return operation(channel);
            }
            finally
            {
                ((IClientChannel)channel).Dispose();
                factory.Close();
            }
        }
    }
}
using System;
using System.ServiceModel;

using Estate.Contracts;

namespace Estate.Hub
{
    /// <summary>
    /// The on-prem WCF hub. It does no payment work itself: it picks the payment service
    /// for the request's workload and environment and forwards the operation.
    /// </summary>
    /// <seealso cref="IPaymentService.Post(PaymentRequest)"/>
    [ServiceBehavior(InstanceContextMode = InstanceContextMode.PerCall)]
    public class PaymentHub : IPaymentHub
    {
        public PaymentResult PostPayment(PaymentRequest request)
        {
            return Forward(request.Workload, request.Environment, service => service.Post(request));
        }

        public PaymentResult GetPayment(PaymentQuery query)
        {
            return Forward(query.Workload, query.Environment, service => service.Get(query));
        }

        private static T Forward<T>(string workload, string environment, Func<IPaymentService, T> operation)
        {
            var factory = new ChannelFactory<IPaymentService>(ServiceRouting.EndpointNameFor(workload, environment));
            IPaymentService channel = factory.CreateChannel();
            try
            {
                return operation(channel);
            }
            finally
            {
                ((IClientChannel)channel).Dispose();
                factory.Close();
            }
        }
    }
}
namespace Estate.Hub
{
    /// <summary>Names the client endpoint (App.config, system.serviceModel/client) that serves a workload and environment.</summary>
    public static class ServiceRouting
    {
        public const string EndpointPrefix = "PaymentService";

        public static string EndpointNameFor(string workload, string environment)
        {
            return EndpointPrefix + "." + workload + "." + environment;
        }
    }
}
using Estate.Contracts;
using Estate.Payments.Data;

namespace Estate.Payments
{
    /// <summary>The on-prem WCF payment service. Posting goes through a stored procedure; lookups go through Entity Framework.</summary>
    public class PaymentService : IPaymentService
    {
        public PaymentResult Post(PaymentRequest request)
        {
            using (var db = new PaymentsContext())
            {
                PostPaymentRow row = db.PostPayment(request.AccountNumber, request.Amount);
                return new PaymentResult
                {
                    PaymentId      = row.PaymentId,
                    Status         = row.Status,
                    AccountBalance = row.AccountBalance
                };
            }
        }

        public PaymentResult Get(PaymentQuery query)
        {
            using (var db = new PaymentsContext())
            {
                Payment payment = db.Payments.Find(query.PaymentId);
                if (payment == null)
                {
                    return null;
                }
                return new PaymentResult
                {
                    PaymentId      = payment.PaymentId,
                    Status         = payment.Status,
                    AccountBalance = 0m
                };
            }
        }
    }
}
using System.Data.Entity;
using System.Data.SqlClient;
using System.Linq;

namespace Estate.Payments.Data
{
    /// <summary>
    /// Entity Framework context over the on-prem Payments database. The connection string
    /// is App.config's "PaymentsDb". Posting a payment calls dbo.usp_PostPayment, which is
    /// where the linked-server read of the Oracle account balance happens.
    /// </summary>
    public class PaymentsContext : DbContext
    {
        public const string ConnectionName       = "PaymentsDb";
        public const string PostPaymentProcedure = "dbo.usp_PostPayment";

        public PaymentsContext() : base("name=" + ConnectionName)
        {
        }

        public DbSet<Payment> Payments { get; set; }

        public PostPaymentRow PostPayment(string accountNumber, decimal amount)
        {
            return Database.SqlQuery<PostPaymentRow>(
                "EXEC " + PostPaymentProcedure + " @AccountNumber, @Amount",
                new SqlParameter("@AccountNumber", accountNumber),
                new SqlParameter("@Amount",        amount)).Single();
        }
    }
}
CREATE TABLE dbo.Payment
(
    PaymentId     NVARCHAR(36)   NOT NULL PRIMARY KEY,
    AccountNumber NVARCHAR(32)   NOT NULL,
    Amount        DECIMAL(18, 2) NOT NULL,
    Status        NVARCHAR(16)   NOT NULL,
    PostedAt      DATETIME2      NOT NULL
);
-- Posts a payment and returns the account balance from the system of record.
-- The balance lives in the Oracle database reached through the ORACLE_CENTRAL linked server.
CREATE PROCEDURE dbo.usp_PostPayment
    @AccountNumber NVARCHAR(32),
    @Amount        DECIMAL(18, 2)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @PaymentId NVARCHAR(36) = CONVERT(NVARCHAR(36), NEWID());

    INSERT INTO dbo.Payment (PaymentId, AccountNumber, Amount, Status, PostedAt)
    VALUES (@PaymentId, @AccountNumber, @Amount, N'Posted', SYSUTCDATETIME());

    SELECT @PaymentId                          AS PaymentId,
           N'Posted'                           AS Status,
           CONVERT(DECIMAL(18, 2), a.BALANCE)  AS AccountBalance
    FROM   ORACLE_CENTRAL..CENTRAL.ACCOUNT AS a
    WHERE  a.ACCOUNT_NO = @AccountNumber;
END;
